const PAYLOAD = [{"id":"pnj-aseryns-terres-temples-cassandra-serkis-17","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Cassandra Serkis","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Mû","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Cassandra Serkis","real_name_source":"Cassandra Serkis","nom_verite":"Cassia Seryn","nom_verite_source":"Cassia Seryn","race":"Aseryne (Paleo-atlante)","age":"35 ans","origine":"Américaine","statut":"duchesse","affiliations":"Gouvernement : Sénat","source_group":"Mû","source_order":17,"source_page":20,"identity_keys":["Cassia Seryn","Cassandra Serkis"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché d’Austilla : Cassia Seryn Nom de la Réalité : Cassandra Serkis Nom de la Vérité : Cassia Seryn Age : «35 ans » - ??? Affiliations : Gouvernement : Sénat Nationalité d’origine : Américaine Ethnie réelle : Aseryne (Paleo-atlante) Statut : duchesse Cassandra Serkis est une sénatrice de Californie, Elle est assez jeune pour être au Sénat et assez séduisante, mais elle n’a pas spécialement usurpé sa place. Partisane assez conservatrice, elle est difficile à convaincre quand il faut voter des lois plus modernes, en revanche, elle est entièrement anti￾corporatiste. Humaniste, elle est une donatrice assidue à la fondation Graff. C’est une duchesse ancienne, de la maison Seryn, lors du cataclysme, sa mère, Aklessia, se plaça en stase dans le tombeau ducal du duché de Leanadur, Cassia et Nessia, la sœur, préférèrent fuir. Nessia avait un fils, Jesaen, lequel vivait sur Aèr, elle abandonna donc la Terre pour le joindre alors que Cassia resta sur son navire pour attendre afin de retourner sur l’Atlantide au plus vite une fois la mer retirée. Cela n’arriva pas et elle suivit Kyriak, prenant le titre de duchesse de Leanadur, de la maison Seryn. Quand Mylakai remonta le continent Atlante, Jesaen réclama être le seul duc de Leanadur quand le sarcophage d’Aklessia fut trouvé profané, un profond ancien s’y trouvant. Si pour les Paleo-atlantes, Cassia est la duchesse légitime, pour la cour de Lorinae et ses partisans, Jesaen étant un homme d’honneur depuis toujours, il est inconcevable de lui retirer son titre.","source_pages":[20,20],"source_designation":"Duché d’Austilla : Cassia Seryn"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Cassandra Serkis"],["Âge apparent","35 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Cassandra Serkis est une sénatrice de Californie. Elle est assez jeune pour être au Sénat et assez séduisante, mais elle n’a pas spécialement usurpé sa place. Partisane assez conservatrice, elle est difficile à convaincre quand il faut voter des lois plus modernes, en revanche, elle est entièrement anti-corporatiste. Humaniste, elle est une donatrice assidue à la fondation Graff."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché d’Austilla : Cassia Seryn"],["Nom de la Réalité","Cassandra Serkis"],["Nom de la Vérité","Cassia Seryn"],["Âge complet","35 ans en apparence ; âge réel inconnu"],["Affiliations","Gouvernement : Sénat"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (Paleo-atlante)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"C’est une duchesse ancienne, de la maison Seryn, lors du cataclysme, sa mère, Aklessia, se plaça en stase dans le tombeau ducal du duché de Leanadur, Cassia et Nessia, la sœur, préférèrent fuir. Nessia avait un fils, Jesaen, lequel vivait sur Aèr, elle abandonna donc la Terre pour le joindre alors que Cassia resta sur son navire pour attendre afin de retourner sur l’Atlantide au plus vite une fois la mer retirée. Cela n’arriva pas et elle suivit Kyriak, prenant le titre de duchesse de Leanadur, de la maison Seryn. Quand Mylakai remonta le continent Atlante, Jesaen réclama être le seul duc de Leanadur quand le sarcophage d’Aklessia fut trouvé profané, un profond ancien s’y trouvant. Si pour les Paleo-atlantes, Cassia est la duchesse légitime, pour la cour de Lorinae et ses partisans, Jesaen étant un homme d’honneur depuis toujours, il est inconcevable de lui retirer son titre."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-gloria-drake-18","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Gloria Drake","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Mû","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Gloria Drake","real_name_source":"Gloria Drake","nom_verite":"Aloria Dratyn","nom_verite_source":"Aloria Dratyn","race":"aseryne (Mûlienne)","age":"34 ans","origine":"atlante","statut":"duchesse","affiliations":"crawlers : mercs / chasseurs (Association)","source_group":"Mû","source_order":18,"source_page":20,"identity_keys":["Aloria Dratyn","Gloria Drake"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché d’Asiria : Aloria Dratyn Nom de la Réalité : Gloria Drake Nom de la Vérité : Aloria Dratyn Age : «34 ans » - ??? Affiliations : crawlers : mercs / chasseurs (Association) Nationalité d’origine : atlante Ethnie réelle : aseryne (Mûlienne) Statut : duchesse G-drake est une mercs aussi badass que solitaire, son armure Sedhia craft est une véritable œuvre d’art et se base sur une structure qu’elle a elle-même conçu. En vérité c’est une chasseuse du hunt100, spécialisée dans les créatures des grottes et des fonds marins. Son armure est en Stroethil, un métal unique et introuvable sur les continents connus. Abusée par une créature des profondeurs, elle n’a de cesse de toutes les purger désormais, surtout sa fille, ayant été contrainte à porter cette engeance. Elle était de la maison Natheas et fut placée en Stase, elle était une des quatre filles de la Duchesse, Siressia Natheas. Quand elle se réveilla, ce ne fut que pour constater une scène immonde où ses sœurs comme elle-même étaient prises par des profonds. Leur mère n’était plus en Stase. Ses sœurs furent tuées quand elle décida de lutter, s’échappant in extremis. Hélas, elle réalisa être enceinte et accoucha quelques jours à peine après son réveil, l’enfant, une petite fille aseryne en apparence appela de ses cris un fléau mais aussi le vieil atlante Erlaris qui tua le fléau mineur. Il confirma que sa mère avait quitté l’Atlantide pour Aèr, abandonnant ses filles. Changeant de nom, Aloria s’échappa de l’île submergée et trouva Mû, vouant une haine aux Natheas d’Aerilin et plus encore aux profonds.","source_pages":[20,20],"source_designation":"Duché d’Asiria : Aloria Dratyn"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Gloria Drake"],["Âge apparent","34 ans"],["Nationalité déclarée","Non renseignée"]]},{"type":"p","text":"G-drake est une mercenaire aussi badass que solitaire, son armure Sedhia craft est une véritable œuvre d’art et se base sur une structure qu’elle a elle-même conçue."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché d’Asiria : Aloria Dratyn"],["Nom de la Réalité","Gloria Drake"],["Nom de la Vérité","Aloria Dratyn"],["Âge complet","34 ans en apparence ; âge réel inconnu"],["Affiliations","crawlers : mercs / chasseurs (Association)"],["Nationalité d’origine","atlante"],["Nature réelle","aseryne (Mûlienne)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"En vérité c’est une chasseuse du hunt100, spécialisée dans les créatures des grottes et des fonds marins. Son armure est en Stroethil, un métal unique et introuvable sur les continents connus. Abusée par une créature des profondeurs, elle n’a de cesse de toutes les purger désormais, surtout sa fille, ayant été contrainte à porter cette engeance. Elle était de la maison Natheas et fut placée en Stase, elle était une des quatre filles de la Duchesse, Siressia Natheas. Quand elle se réveilla, ce ne fut que pour constater une scène immonde où ses sœurs comme elle-même étaient prises par des profonds. Leur mère n’était plus en Stase. Ses sœurs furent tuées quand elle décida de lutter, s’échappant in extremis. Hélas, elle réalisa être enceinte et accoucha quelques jours à peine après son réveil, l’enfant, une petite fille aseryne en apparence appela de ses cris un fléau mais aussi le vieil atlante Erlaris qui tua le fléau mineur. Il confirma que sa mère avait quitté l’Atlantide pour Aèr, abandonnant ses filles. Changeant de nom, Aloria s’échappa de l’île submergée et trouva Mû, vouant une haine aux Natheas d’Aerilin et plus encore aux profonds."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-valeria-warner-silver-19","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Valeria Warner-Silver","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Mû","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Valeria Warner-Silver","real_name_source":"Valeria Warner-Silver","nom_verite":"Saerith Visilas Zenos","nom_verite_source":"Saerith Visilas Zenos","race":"Aseryne (Mûlienne)","age":"76 ans","origine":"Américaine","statut":"fille du roi","affiliations":"corporatiste : seaware","source_group":"Mû","source_order":19,"source_page":21,"identity_keys":["Saerith Visilas Zenos","Valeria Warner-Silver"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Princesse bâtarde: Saerith Visilas Zenos Nom de la Réalité : Valeria Warner-Silver Nom de la Vérité : Saerith Visilas Zenos Age : « 76 ans » - ??? Affiliations : corporatiste : seaware Nationalité d’origine : Américaine Ethnie réelle : Aseryne (Mûlienne) Statut : fille du roi Malgré ses 76 ans, Valeria, par des cures de jouvence de Biosun, semble avoir ses trente ans. Blonde platine plus que sculpturale, cette mangeuse d’hommes est une femme d’affaire plutôt douée. Autrefois secrétaire à la mairie de Los Angeles elle se maria à Todd Silver et eu un seul fils : John. Princesse « bâtarde », de Kyriak, elle est une des nombreuses filles du roi qui cherchent à hameçonner un noble atlante pour faire rallier le plus de grande maison à la cause Mûlienne. En marge de ce vaste jeu, elle se trouva un humain lui plaisant et fonda une famille, par son caractère impulsif et téméraire, elle coupa les ponts avec Mü. Elle ignorait que son propre fils intéressait Kalira Athegos en personne pendant qu’elle essayait de suivre la voie du Temple quelques années, en vain, trop indisciplinée. Quand elle arrêta sa formation au temple, son fils était mort et sa petite fille en famille d’accueil, ayant disparu 25 ans, sans vieillir, personne n’accepta qu’elle fût la citoyenne qu’elle prétendait être. Prise d’une infinie colère, elle provoqua un léger orage et planifia surtout l’assassinat d’un duc Atlante en représailles. On ignore qui était le père de son fils. Todd Silver n’étant qu’une fausse identité.","source_pages":[21,21],"source_designation":"Princesse bâtarde : Saerith Visilas Zenos"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Valeria Warner-Silver"],["Âge apparent","76 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Malgré ses 76 ans, Valeria, par des cures de jouvence de Biosun, semble avoir ses trente ans. Blonde platine plus que sculpturale, cette mangeuse d’hommes est une femme d’affaires plutôt douée. Autrefois secrétaire à la mairie de Los Angeles elle se maria à Todd Silver et eut un seul fils : John."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Princesse bâtarde: Saerith Visilas Zenos"],["Nom de la Réalité","Valeria Warner-Silver"],["Nom de la Vérité","Saerith Visilas Zenos"],["Âge complet","76 ans en apparence ; âge réel inconnu"],["Affiliations","corporatiste : seaware"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (Mûlienne)"],["Statut","fille du roi"]]},{"type":"p","style":"lore","text":"Princesse « bâtarde », de Kyriak, elle est une des nombreuses filles du roi qui cherchent à hameçonner un noble atlante pour faire rallier le plus de grande maison à la cause Mûlienne. En marge de ce vaste jeu, elle se trouva un humain lui plaisant et fonda une famille, par son caractère impulsif et téméraire, elle coupa les ponts avec Mü. Elle ignorait que son propre fils intéressait Kalira Athegos en personne pendant qu’elle essayait de suivre la voie du Temple quelques années, en vain, trop indisciplinée. Quand elle arrêta sa formation au temple, son fils était mort et sa petite fille en famille d’accueil, ayant disparu 25 ans, sans vieillir, personne n’accepta qu’elle fût la citoyenne qu’elle prétendait être. Prise d’une infinie colère, elle provoqua un léger orage et planifia surtout l’assassinat d’un duc Atlante en représailles. On ignore qui était le père de son fils. Todd Silver n’étant qu’une fausse identité."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-victoria-warner-20","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Victoria Warner","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Mû","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Victoria Warner","real_name_source":"Victoria Warner","nom_verite":"Vaelirei Selerias Zenos","nom_verite_source":"?","race":"Aseryne (Mûlienne)","age":"56 ans","origine":"Américaine","statut":"fille du roi","affiliations":"corporatiste : eversor","source_group":"Mû","source_order":20,"source_page":21,"identity_keys":["Vaelirei Selerias Zenos","Victoria Warner"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Princesse bâtarde : Vaelirei Selerias Zenos Nom de la Réalité : Victoria Warner Nom de la Vérité : ? Age : « 56 ans » - ??? Affiliations : corporatiste : eversor Nationalité d’origine : Américaine Ethnie réelle : Aseryne (Mûlienne) Statut : fille du roi Victoria Warner était un cadre d’ocean master, elle avait la charge de la gestion de nouvelles souches d’algues productrices d’électricité. Le projet échoua à cause de fortes tempêtes et de soucis de matériaux. Les supérieurs de Victoria voulaient se débarrasser du projet trop couteux, la venue inespérée de Saskia fut l’occasion. En, vérité, l’occasion fut plus grande encore pour Victoria qui utilisa ses résultats et les nouveaux moyens donnés par Saskia pour achever le projet. Calme et provocatrice, elle aime assez vivre nue sous sa blouse de scientifique pour déconcentrer. Fille de Kyriak, elle devait être mariée à un cousin de duc Atlante, cependant, il fut tué avec ledit duc par les assassins de Saerith, la sœur de Vaelirei. Elle se voua donc à ses travaux sur les algues mûliennes dont des souches corrompues par Thul. Tombée folle de Saskia, elle décida de joindre sa corporation pour l’aider tout autant que pour s’éloigner des siens. Elle a récemment développé quelques dons électriques lors de l’orage surnaturel du port que provoqua Veronica Silver, comme quelques autres femmes de la lignée, comme si l’éveil de Veronica avait un impact sur elles.","source_pages":[21,21],"source_designation":"Princesse bâtarde : Vaelirei Selerias Zenos"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Victoria Warner"],["Âge apparent","56 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Victoria Warner était un cadre d’Ocean Master, elle avait la charge de la gestion de nouvelles souches d’algues productrices d’électricité. Le projet échoua à cause de fortes tempêtes et de soucis de matériaux. Les supérieurs de Victoria voulaient se débarrasser du projet trop coûteux, la venue inespérée de Saskia fut l’occasion. En vérité, l’occasion fut plus grande encore pour Victoria qui utilisa ses résultats et les nouveaux moyens donnés par Saskia pour achever le projet. Calme et provocatrice, elle aime assez vivre nue sous sa blouse de scientifique pour déconcentrer."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Princesse bâtarde : Vaelirei Selerias Zenos"],["Nom de la Réalité","Victoria Warner"],["Nom de la Vérité","Vaelirei Selerias Zenos"],["Âge complet","56 ans en apparence ; âge réel inconnu"],["Affiliations","corporatiste : eversor"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (Mûlienne)"],["Statut","fille du roi"]]},{"type":"p","style":"lore","text":"Fille de Kyriak, elle devait être mariée à un cousin de duc Atlante, cependant, il fut tué avec ledit duc par les assassins de Saerith, la sœur de Vaelirei. Elle se voua donc à ses travaux sur les algues mûliennes dont des souches corrompues par Thul. Tombée folle de Saskia, elle décida de joindre sa corporation pour l’aider tout autant que pour s’éloigner des siens. Elle a récemment développé quelques dons électriques lors de l’orage surnaturel du port que provoqua Veronica Silver, comme quelques autres femmes de la lignée, comme si l’éveil de Veronica avait un impact sur elles."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-denise-zane-21","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Denise Zane","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Mû","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Denise Zane","real_name_source":"Denise Zane","nom_verite":"Deidea Eina Zenos / Coronis","nom_verite_source":"Deidea Eina Zenos / Coronis","race":"Aseryn (Mûlienne)","age":"25 ans","origine":"Américaine","statut":"fille du roi","affiliations":"Corporatiste : Phantasmedia","source_group":"Mû","source_order":21,"source_page":22,"identity_keys":["Deidea Eina Zenos","Denise Zane","Deidea Eina Zenos / Coronis","Coronis"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Princesse bâtarde: Deidea Eina Zenos Nom de la Réalité : Denise Zane Nom de la Vérité : Deidea Eina Zenos / Coronis Age : « 25 ans » Affiliations : Corporatiste : Phantasmedia Nationalité d’origine : Américaine Ethnie réelle : Aseryn (Mûlienne) Statut : fille du roi Denise Zane est la jeune présidente de la corporation Phantasmedia, une petite « concurrente » de la Tuatha. Ambitieuse et relativement innovante dans les concepts de divertissements qu’elle propose, elle s’est montrée impitoyable pour se faire une place, utilisant la pègre à ses fins. Deidea est une fille de Kyriak et n’entend absolument pas laisser compter un ordre d’ainesse pour la couronne Mûlienne. Elle n’a rien à envier au duc Nagilia, à ce jour, quatre de ses sœurs ont été éliminées sur ses ordres et près de neufs descendants nobles de l’Atlantide ainsi que deux d’Hyperborée. Elle pave son accession au trône par un tapis sanglant. Derrière ses airs de Siobhain au rabais, elle cache une triste vérité, la daemone Astarté l’a contrainte à pactiser avec la nymphe Coronis, des hyades, afin qu’elle n’habite son corps, lui conférant l’immense affinité avec la foudre qu’elle n’avait pas pour prétendre au trône. Possédée totalement par la nymphe, elle œuvre pour le culte d’Abigor, si elle devient reine de Mû, ayant le devoir d’abattre le Temple de la Création au profit du cultes des anciens dieux. Deidea et Coronis habitant le même corps, leurs âmes s’entremêlent et leurs personnalités fusionnent, mais la nymphe conserve l'ascendant très clairement.","source_pages":[22,22],"source_designation":"Princesse bâtarde : Deidea Eina Zenos"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Denise Zane"],["Âge apparent","25 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Denise Zane est la jeune présidente de la corporation Phantasmedia, une petite « concurrente » de la Tuatha. Ambitieuse et relativement innovante dans les concepts de divertissements qu’elle propose, elle s’est montrée impitoyable pour se faire une place, utilisant la pègre à ses fins."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Princesse bâtarde: Deidea Eina Zenos"],["Nom de la Réalité","Denise Zane"],["Nom de la Vérité","Deidea Eina Zenos / Coronis"],["Âge complet","25 ans en apparence ; âge réel inconnu"],["Affiliations","Corporatiste : Phantasmedia"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryn (Mûlienne)"],["Statut","fille du roi"]]},{"type":"p","style":"lore","text":"Deidea est une fille de Kyriak et n’entend absolument pas laisser compter un ordre d’ainesse pour la couronne Mûlienne. Elle n’a rien à envier au duc Nagilia, à ce jour, quatre de ses sœurs ont été éliminées sur ses ordres et près de neufs descendants nobles de l’Atlantide ainsi que deux d’Hyperborée. Elle pave son accession au trône par un tapis sanglant. Derrière ses airs de Siobhain au rabais, elle cache une triste vérité, la daemone Astarté l’a contrainte à pactiser avec la nymphe Coronis, des hyades, afin qu’elle n’habite son corps, lui conférant l’immense affinité avec la foudre qu’elle n’avait pas pour prétendre au trône. Possédée totalement par la nymphe, elle œuvre pour le culte d’Abigor, si elle devient reine de Mû, ayant le devoir d’abattre le Temple de la Création au profit du cultes des anciens dieux. Deidea et Coronis habitant le même corps, leurs âmes s’entremêlent et leurs personnalités fusionnent, mais la nymphe conserve l'ascendant très clairement."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-nakshatra-pandey-22","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Nakshatra Pandey","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Lémurie","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Nakshatra Pandey","real_name_source":"Nakshatra Pandey","nom_verite":"Corman Atreios","nom_verite_source":"Corman Atreios","race":"Aseryne (lemurianne)","age":"48 ans","origine":"Indienne","statut":"Roi des Lemurians","affiliations":"corporatiste : Wellspring","source_group":"Lémurie","source_order":22,"source_page":26,"identity_keys":["Corman Atreios","Nakshatra Pandey"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Lemuris (royal) : Corman Atreios Nom de la Réalité : Nakshatra Pandey Nom de la Vérité : Corman Atreios Age : «48 ans » - ??? ns Affiliations : corporatiste : Wellspring Nationalité d’origine : Indienne Ethnie réelle : Aseryne (lemurianne) Statut : Roi des Lemurians Nakshatra est un corporatiste d’importance, actuellement, il a été destitué de son statut de directeur dessous-branche, il a donc seulement la direction de l’entreprise « Enew-G ». Il vient de temps en temps en Californie pour le travail. Acide et pessimiste, il se sait gravement menacé à Wellspring, il cherche donc des alliés en Californie. Duc de Zirilia, c’est le roi élu de Lemuria, il se réclame du sang Athegos et lorgne sur le trône Atlante. C’est un vrai lemurian, un aseryn avec pas mal de sang humain et nymphoïde. Protégé d’Alabor, il vient en Californie sur ses ordres, car la déesse apprécierait grandement que le roi Atlante soit un de ses serviteurs. Hélas, les Lemurians n’ont pas beaucoup d’influence en Californie, les Muliens y étant profondément ancrés et les Atlantes ne se ménagent pas non plus. C’est par les nymphes que Corman voulait jouer sa carte maitresse, mais leur quasi-inexistence en Californie a été sa plus grosse erreur de jugement. Proche des Daemons d’Alabor, Corman est possiblement dérouté : dans la course au trône Atlante, il n’a pas le poids qu’il pensait avoir ni moyen de négocier quoi que ce soit. Il se sait condamné à échouer, non sans frustration.","source_pages":[26,26],"source_designation":"Duché de Lemuris (royal) : Corman Atreios"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Nakshatra Pandey"],["Âge apparent","48 ans"],["Nationalité déclarée","Indienne"]]},{"type":"p","text":"Nakshatra est un corporatiste d’importance, actuellement, il a été destitué de son statut de directeur de sous-branche, il a donc seulement la direction de l’entreprise « Enew-G ». Il vient de temps en temps en Californie pour le travail. Acide et pessimiste, il se sait gravement menacé à Wellspring, il cherche donc des alliés en Californie."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Lemuris (royal) : Corman Atreios"],["Nom de la Réalité","Nakshatra Pandey"],["Nom de la Vérité","Corman Atreios"],["Âge complet","48 ans en apparence ; âge réel inconnu"],["Affiliations","corporatiste : Wellspring"],["Nationalité d’origine","Indienne"],["Nature réelle","Aseryne (lemurianne)"],["Statut","Roi des Lemurians"]]},{"type":"p","style":"lore","text":"Duc de Zirilia, c’est le roi élu de Lemuria, il se réclame du sang Athegos et lorgne sur le trône Atlante. C’est un vrai lemurian, un aseryn avec pas mal de sang humain et nymphoïde. Protégé d’Alabor, il vient en Californie sur ses ordres, car la déesse apprécierait grandement que le roi Atlante soit un de ses serviteurs. Hélas, les Lemurians n’ont pas beaucoup d’influence en Californie, les Muliens y étant profondément ancrés et les Atlantes ne se ménagent pas non plus. C’est par les nymphes que Corman voulait jouer sa carte maîtresse, mais leur quasi-inexistence en Californie a été sa plus grosse erreur de jugement. Proche des Daemons d’Alabor, Corman est possiblement dérouté : dans la course au trône Atlante, il n’a pas le poids qu’il pensait avoir ni moyen de négocier quoi que ce soit. Il se sait condamné à échouer, non sans frustration."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-dira-chetti-23","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Dira Chetti","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Lémurie","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Dira Chetti","real_name_source":"Dira Chetti","nom_verite":"Dirayanti Shrivetti","nom_verite_source":"Dirayanti Shrivetti","race":"Aseryne (lemurianne)","age":"31 ans","origine":"Indienne","statut":"duchesse","affiliations":"Crawlers : hookers","source_group":"Lémurie","source_order":23,"source_page":26,"identity_keys":["Dirayanti Shrivetti","Dira Chetti"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché d’Amunghol: Dirayanti Shrivetti Nom de la Réalité : Dira Chetti Nom de la Vérité : Dirayanti Shrivetti Age : « 31 ans » - ???? ans Affiliations : Crawlers : hookers Nationalité d’origine : Indienne Ethnie réelle : Aseryne (lemurianne) Statut : duchesse Dira est une beauté indienne aux cheveux auburn aussi séduisante que chaleureuse. Propriétaire d’un très grand restaurant indien, elle résiste aux mafieux et aux corporatistes par sa fortune familiale, cependant, son argent part bien trop vite. Elle fait donc du renseignement, utilisant ses charmes pour se mêler à la jet set, c’est une « crawlers » de luxe, un caméléon dans l’environnement des riches qui n’hésites pas à former des équipes de crawlers pour espionner ou bien voler parfois, jamais soupçonnée. Bien que dans la réalité, elle vive de sa capacité à charmer et arnaquer, elle est une très noble duchesse aseryne de Lemurie en Vérité. Corman n’était pas réélu aux dernières élections du duché de Lemuris, c’est Dirayanti qui, trahissant ses alliances avec le candidat qu’elle devait choisir, changea d’avis et lui offrit à nouveau la couronne. Ce service, il lui paye au centuple jusqu’à la prochaine élection et elle s’assure qu’il ne manque jamais de reconnaissance. S’il est perdu et ne sait comment s’imposer pour le trône Atlante, Dira possède un plan assez simple basé sur l’élimination de Kyriak, de Lorinae et tout autre prétendant au trône. Elle espère ainsi devenir reine par mariage une fois Corman établi.","source_pages":[26,26],"source_designation":"Duché d’Amunghol : Dirayanti Shrivetti"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Dira Chetti"],["Âge apparent","31 ans"],["Nationalité déclarée","Indienne"]]},{"type":"p","text":"Dira est une beauté indienne aux cheveux auburn aussi séduisante que chaleureuse. Propriétaire d’un très grand restaurant indien, elle résiste aux mafieux et aux corporatistes par sa fortune familiale, cependant, son argent part bien trop vite. Elle fait donc du renseignement, utilisant ses charmes pour se mêler à la jet set, c’est une crawler de luxe, un caméléon dans l’environnement des riches qui n’hésite pas à former des équipes de crawlers pour espionner ou bien voler parfois, jamais soupçonnée."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché d’Amunghol: Dirayanti Shrivetti"],["Nom de la Réalité","Dira Chetti"],["Nom de la Vérité","Dirayanti Shrivetti"],["Âge complet","31 ans en apparence ; âge réel inconnu"],["Affiliations","Crawlers : hookers"],["Nationalité d’origine","Indienne"],["Nature réelle","Aseryne (lemurianne)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"Bien que dans la réalité, elle vive de sa capacité à charmer et arnaquer, elle est une très noble duchesse aseryne de Lemurie en Vérité. Corman n’était pas réélu aux dernières élections du duché de Lemuris, c’est Dirayanti qui, trahissant ses alliances avec le candidat qu’elle devait choisir, changea d’avis et lui offrit à nouveau la couronne. Ce service, il lui paye au centuple jusqu’à la prochaine élection et elle s’assure qu’il ne manque jamais de reconnaissance. S’il est perdu et ne sait comment s’imposer pour le trône Atlante, Dira possède un plan assez simple basé sur l’élimination de Kyriak, de Lorinae et tout autre prétendant au trône. Elle espère ainsi devenir reine par mariage une fois Corman établi."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-muya-mitchell-24","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Muya Mitchell","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Lémurie","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Muya Mitchell","real_name_source":"Muya Mitchell","nom_verite":"Anmuya Bhatthias","nom_verite_source":"Anmuya Bhatthias","race":"Aseryne (Paleo-atlante)","age":"26 ans","origine":"Américaine","statut":"duchesse","affiliations":"crawlers : fixer","source_group":"Lémurie","source_order":24,"source_page":27,"identity_keys":["Anmudya Bhattias","Muya Mitchell","Anmuya Bhatthias"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Damadyra: Anmudya Bhattias Nom de la Réalité : Muya Mitchell Nom de la Vérité : Anmuya Bhatthias Age : «26 ans » - ??? Affiliations : crawlers : fixer Nationalité d’origine : Américaine Ethnie réelle : Aseryne (Paleo-atlante) Ethnie réelle : Aseryne (lemurianne) Statut : duchesse Muya est un des fixers qui officient à l’international, on ne sait pas vraiment ses véritables origines, si elle est un peu afro-américaine, indienne ou pakistanaise, avec sa peau sombre mais ses traits très occidentaux avec ses yeux clairs. Elle appartient à une boite de fixers, les « Ziiro ». Sa faction est souvent en opposition avec la Blanchisserie ou les fixers très locaux puisqu’elle étend un système plus proche d’une corporation. Duchesse de Damadyra, elle cherche en Californie à traiter avec Faust pour établir une cure génique afin de rendre les Lemurians moins sensibles à l’Ardeomerose lemuriannis, une maladie uniquement sur le continent aseryn de Lemurie qui ravage encore la campagne et les quartiers les plus pauvres. Elle n’a rien à faire de la lutte de pouvoir pour le trône royal des aseryns. Parce qu’elle est Lemurianne, elle entrevoit un avenir avec un sénat des rois aseryns, où le vote et la discussion priment sur les lignées d’autant plus les Athegos sont selon elle la cause des soucis de tous les Aseryns.","source_pages":[27,27],"source_designation":"Duché de Damadyra : Anmudya Bhattias"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Muya Mitchell"],["Âge apparent","26 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Muya est un des fixers qui officient à l’international, on ne sait pas vraiment ses véritables origines, si elle est un peu afro-américaine, indienne ou pakistanaise, avec sa peau sombre mais ses traits très occidentaux avec ses yeux clairs. Elle appartient à une boîte de fixers, les « Ziiro ». Sa faction est souvent en opposition avec la Blanchisserie ou les fixers très locaux puisqu’elle étend un système plus proche d’une corporation."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Damadyra: Anmudya Bhattias"],["Nom de la Réalité","Muya Mitchell"],["Nom de la Vérité","Anmuya Bhatthias"],["Âge complet","26 ans en apparence ; âge réel inconnu"],["Affiliations","crawlers : fixer"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (Paleo-atlante)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"Duchesse de Damadyra, elle cherche en Californie à traiter avec Faust pour établir une cure génique afin de rendre les Lemurians moins sensibles à l’Ardeomerose lemuriannis, une maladie uniquement sur le continent aseryn de Lemurie qui ravage encore la campagne et les quartiers les plus pauvres. Elle n’a rien à faire de la lutte de pouvoir pour le trône royal des aseryns. Parce qu’elle est Lemurianne, elle entrevoit un avenir avec un sénat des rois aseryns, où le vote et la discussion priment sur les lignées d’autant plus les Athegos sont selon elle la cause des soucis de tous les Aseryns."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-gaetan-rahanitraniriana-25","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Gaétan Rahanitraniriana","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Lémurie","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Gaétan Rahanitraniriana","real_name_source":"Gaétan Rahanitraniriana","nom_verite":"Gurn Mundryas","nom_verite_source":"Gurn Mundryas","race":"Aseryne (lemurianne)","age":"64 ans","origine":"Malgache","statut":"duc","affiliations":"religieux : neopaïens","source_group":"Lémurie","source_order":25,"source_page":27,"identity_keys":["Gurn Mundryas","Gaétan Rahanitraniriana"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Lemagisara : Gurn Mundryas Nom de la Réalité : Gaétan Rahanitraniriana Nom de la Vérité : Gurn Mundryas Age : «64 ans » - ??? Affiliations : religieux : neopaïens Nationalité d’origine : Malgache Ethnie réelle : Aseryne (lemurianne) Statut : duc Gaetan est né à Madagascar d’un père indien et d’une mère malgache. Il n’a jamais été très riche par sa mère l’ayant élevé seule, alors assez jeune, il s’est engagé dans la marine, afin de protéger l’espace maritime délaissé. Le manque de moyens et d’effectifs le poussa à devenir un Fusillier de marine d’une rare compétence, tant il y en a peu et leur rôle était mal déterminé. Pendant la grande guerre contre la Corée, Madagascar envoya un de ses bateaux et ses fusiliers, espérant qu’en ralliant l’effort général, les retombées seraient bénéfiques, mais, hélas, cette bonne volonté envoya juste ses forces marines à la destruction. Gaetan néanmoins survécu et resta avec les résistants Japonais. Il se voua par la suite à la religion et la paix pour fuir ses cauchemars de vétéran. Duc de Lemagisara, il préféra joindre la guerre dans la Réalité pour exercer ses marins, les disséminant dans diverses forces asiatiques. Reconnu comme un amiral de génie, c’est aussi un excellent combattant. Il ne soutient pas du tout Corman, son roi, dans sa course au trône aseryn, qui n’a aucun sens pour lui : La reine Lorinae est légitime et il la reconnait en tant que duc, hélas, les ducs Atlantes et Muliens n’ont aucune considération pour ceux Lemurians, alors son avis n’a aucun poids.","source_pages":[27,27],"source_designation":"Duché de Lemagisara : Gurn Mundryas"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Gaétan Rahanitraniriana"],["Âge apparent","64 ans"],["Nationalité déclarée","Malgache"]]},{"type":"p","text":"Gaétan est né à Madagascar d’un père indien et d’une mère malgache. Il n’a jamais été très riche par sa mère l’ayant élevé seule, alors assez jeune, il s’est engagé dans la marine, afin de protéger l’espace maritime délaissé. Le manque de moyens et d’effectifs le poussa à devenir un fusilier marin d’une rare compétence, tant il y en a peu et leur rôle était mal déterminé. Pendant la grande guerre contre la Corée, Madagascar envoya un de ses bateaux et ses fusiliers, espérant qu’en ralliant l’effort général, les retombées seraient bénéfiques, mais, hélas, cette bonne volonté envoya juste ses forces marines à la destruction. Gaétan survécut néanmoins et resta avec les résistants japonais. Il se voua par la suite à la religion et la paix pour fuir ses cauchemars de vétéran."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Lemagisara : Gurn Mundryas"],["Nom de la Réalité","Gaétan Rahanitraniriana"],["Nom de la Vérité","Gurn Mundryas"],["Âge complet","64 ans en apparence ; âge réel inconnu"],["Affiliations","religieux : neopaïens"],["Nationalité d’origine","Malgache"],["Nature réelle","Aseryne (lemurianne)"],["Statut","duc"]]},{"type":"p","style":"lore","text":"Duc de Lemagisara, il préféra joindre la guerre dans la Réalité pour exercer ses marins, les disséminant dans diverses forces asiatiques. Reconnu comme un amiral de génie, c’est aussi un excellent combattant. Il ne soutient pas du tout Corman, son roi, dans sa course au trône aseryn, qui n’a aucun sens pour lui : La reine Lorinae est légitime et il la reconnait en tant que duc, hélas, les ducs Atlantes et Muliens n’ont aucune considération pour ceux Lemurians, alors son avis n’a aucun poids."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-seung-te-ming-terra-26","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"SEUNG Te-Ming Terra","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Lémurie","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"SEUNG Te-Ming Terra","real_name_source":"SEUNG Te-Ming « Terra »","nom_verite":"Terralith Anirios","nom_verite_source":"Terralith Anirios","race":"Aseryne (lemurianne)","age":"41 ans","origine":"Chinoise","statut":"duchesse","affiliations":"Crawlers : neurodivers","source_group":"Lémurie","source_order":26,"source_page":28,"identity_keys":["Terralith Anirios","SEUNG Te-Ming « Terra »","SEUNG Te-Ming Terra"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Vundis : Terralith Anirios Nom de la Réalité : SEUNG Te-Ming « Terra » Nom de la Vérité : Terralith Anirios Age : « 41 ans » - ??? Affiliations : Crawlers : neurodivers Nationalité d’origine : Chinoise Ethnie réelle : Aseryne (lemurianne) Statut : duchesse « Terra » est une Sino-coréenne qui fut déportée pendant la guerre, informaticienne ayant toujours vécu assez pauvre, elle s’adapta à la guerre et la Californie aisément. Relativement psychopathe, elle a un affect très limité, possiblement affecté par les traumatismes d’une enfance misérable puis ceux de la guerre. Duchesse Aseryne, elle a des traits asiatiques par ses origines plus humaines, sa grand-mère était humaine. Elle est la duchesse de Vundis et préféra quitter Lemuria quelques années pour chercher son arrière-petit-fils, né au Japon, d’une relation entre un de ses descendants et une Mulienne. Elle a un sens de la survie assez développé, elle s’est bien intégrée à la haute Californie. Elle a pour projets personnels, de destituer Corman et la lignée Atreios afin de faire valoir le système aristocratique de Lemuria pleinement. Elle doit néanmoins convaincre les autres ducs de changer de système car, en l’état, sans lien avec une des cinq familles du duché de Lemuris, elle ne pourrait aucunement devenir Reine. Elle complote avec Kelrana Nateas dans ce but, Kelarana estimant « Terra » plus ouverte à se soumettre à la future véritable couronne aseryne qu’elle cherche à instaurer.","source_pages":[28,28],"source_designation":"Duché de Vundis : Terralith Anirios"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","SEUNG Te-Ming Terra"],["Âge apparent","41 ans"],["Nationalité déclarée","Chinoise"]]},{"type":"p","text":"« Terra » est une Sino-coréenne qui fut déportée pendant la guerre, informaticienne ayant toujours vécu assez pauvre, elle s’adapta à la guerre et la Californie aisément. Relativement psychopathe, elle a un affect très limité, possiblement affecté par les traumatismes d’une enfance misérable puis ceux de la guerre."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Vundis : Terralith Anirios"],["Nom de la Réalité","SEUNG Te-Ming « Terra »"],["Nom de la Vérité","Terralith Anirios"],["Âge complet","41 ans en apparence ; âge réel inconnu"],["Affiliations","Crawlers : neurodivers"],["Nationalité d’origine","Chinoise"],["Nature réelle","Aseryne (lemurianne)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"Duchesse Aseryne, elle a des traits asiatiques par ses origines plus humaines, sa grand-mère était humaine. Elle est la duchesse de Vundis et préféra quitter Lemuria quelques années pour chercher son arrière-petit-fils, né au Japon, d’une relation entre un de ses descendants et une Mulienne. Elle a un sens de la survie assez développé, elle s’est bien intégrée à la haute Californie. Elle a pour projets personnels, de destituer Corman et la lignée Atreios afin de faire valoir le système aristocratique de Lemuria pleinement. Elle doit néanmoins convaincre les autres ducs de changer de système car, en l’état, sans lien avec une des cinq familles du duché de Lemuris, elle ne pourrait aucunement devenir Reine. Elle complote avec Kelrana Nateas dans ce but, Kelarana estimant « Terra » plus ouverte à se soumettre à la future véritable couronne aseryne qu’elle cherche à instaurer."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-myckael-hellinberg-27","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Myckael Hellinberg","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Lémurie","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Myckael Hellinberg","real_name_source":"Myckael Hellinberg","nom_verite":"Myderion Elletas","nom_verite_source":"Myderion Elletas","race":"Aseryne (lemurianne)","age":"34 ans","origine":"américaine","statut":"Duc Suppléant","affiliations":"pègre : mafia russe/ crawlers ; cypper","source_group":"Lémurie","source_order":27,"source_page":28,"identity_keys":["Myderion Elletas","Myckael Hellinberg"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"(suppléant) Duché de Lemuris : Myderion Elletas Nom de la Réalité : Myckael Hellinberg Nom de la Vérité : Myderion Elletas Age : «34 ans » - ??? Affiliations : pègre : mafia russe/ crawlers ; cypper Nationalité d’origine : américaine Ethnie réelle : Aseryne (lemurianne) Statut : Duc Suppléant Myckael est un scientifique né de parents russes aux Etats-Unis. Ils ont changé de nom et jamais il n’a vraiment souffert de ses origines. Après des études brillantes au MIT, il intégra un laboratoire exceptionnel. Alors qu’il était sur un projet et que la guerre faisait rage, il intégra le PCRC dans les équipes travaillant sur la mécanique, notamment sous la tutelle de Karamov. Il lui fut alors révélé que toutes ses études avaient été financées par la mafia russe et qu’il devait espionner le PCRC pour envoyer en priorité en Russie les découvertes. Découvert, il fut viré du PCRC puisqu’on ne pouvait prouver qu’il n’envoyait pas en Corée du Nord. Il fut piégé par Lyamina Romanovna d’ailleurs. Paria, il travaille toujours pour la mafia désormais, dans deds laboratoires privés de leurs associations. Duc suppléant du duché de Lemuris, il est un des quatre « sous-ducs » conseillant Corman. De fait, il aurait pu devenir roi plusieurs fois, mais son rival fut élu à chaque fois. C’est un looser, un pauvre type qui n’est jamais victorieux, un scientifique moyen, tout duc Aseryn qu’il est, il s’est fait asservir par des humains comme un idiot. Sans l’aide de Saerith Zenos, il serait probablement déjà mort, tué par des mafieux voulant le punir d’ailleurs, c’est pourquoi il a une dette envers la princesse Mûlienne.","source_pages":[28,28],"source_designation":"Duché de Lemuris (suppléant) : Myderion Elletas"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Myckael Hellinberg"],["Âge apparent","34 ans"],["Nationalité déclarée","américaine"]]},{"type":"p","text":"Myckael est un scientifique né de parents russes aux États-Unis. Ils ont changé de nom et jamais il n’a vraiment souffert de ses origines. Après des études brillantes au MIT, il intégra un laboratoire exceptionnel. Alors qu’il était sur un projet et que la guerre faisait rage, il intégra le PCRC dans les équipes travaillant sur la mécanique, notamment sous la tutelle de Karamov. Il lui fut alors révélé que toutes ses études avaient été financées par la mafia russe et qu’il devait espionner le PCRC pour envoyer en priorité en Russie les découvertes. Découvert, il fut viré du PCRC puisqu’on ne pouvait prouver qu’il n’envoyait pas en Corée du Nord. Il fut piégé par Lyamina Romanovna d’ailleurs. Paria, il travaille toujours pour la mafia désormais, dans des laboratoires privés de leurs associations."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","(suppléant) Duché de Lemuris : Myderion Elletas"],["Nom de la Réalité","Myckael Hellinberg"],["Nom de la Vérité","Myderion Elletas"],["Âge complet","34 ans en apparence ; âge réel inconnu"],["Affiliations","pègre : mafia russe/ crawlers ; cypper"],["Nationalité d’origine","américaine"],["Nature réelle","Aseryne (lemurianne)"],["Statut","Duc Suppléant"]]},{"type":"p","style":"lore","text":"Duc suppléant du duché de Lemuris, il est un des quatre « sous-ducs » conseillant Corman. De fait, il aurait pu devenir roi plusieurs fois, mais son rival fut élu à chaque fois. C’est un looser, un pauvre type qui n’est jamais victorieux, un scientifique moyen, tout duc Aseryn qu’il est, il s’est fait asservir par des humains comme un idiot. Sans l’aide de Saerith Zenos, il serait probablement déjà mort, tué par des mafieux voulant le punir d’ailleurs, c’est pourquoi il a une dette envers la princesse Mûlienne."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-mary-shanasti-28","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Mary Shanasti","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Lémurie","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Mary Shanasti","real_name_source":"Mary Shanasti","nom_verite":"Maarashana","nom_verite_source":"Maarashana","race":"demi-Aseryne, semi-daemone (Lemurianne)","age":"28 ans","origine":"indienne","statut":"Duchesse Suppléante","affiliations":"Crawlers : Enders","source_group":"Lémurie","source_order":28,"source_page":29,"identity_keys":["Maarashana","Mary Shanasti"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"(suppléant) Duché d’Amunghol : Maarashana Nom de la Réalité : Mary Shanasti Nom de la Vérité : Maarashana Age : « 28 ans » Affiliations : Crawlers : Enders Nationalité d’origine : indienne Ethnie réelle : demi-Aseryne, semi-daemone (Lemurianne) Statut : Duchesse Suppléante Mary Shanasti est une « enders », elle est une sorte de gourou qui possède des communautés sous￾marines indépendantes. Elle prône des principes religieux néopaganismes, elle n’a que faire des lois, puisque ses communautés sont soumises à la loi de sa propre « nation ». Fille d’Alabor, cette semi-aseryne est une demi-déesse puissante, elle n’a que des aserynes et de nymphes marines dans ses communautés, elle est farouchement opposée à Seawares et tout impact corporatif alors même que les infrastructures sont construites par ces corporations cherchant à s’installer sous l’eau. Elle était l’ancienne duchesse d’amunghol mais son caractère orageux n’était pas très apprécié et finalement, Amnudya lui fut préférée. Quand elle s’énerve, elle provoque presque toujours la pluie. Les daemons de sa mère la craignent comme la peste, car elle supprime aussi instinctivement leurs pouvoirs pour se les approprier temporairement. Elle déteste les Mûliens, qu’elle trouve présomptueux et stupides mais n’a pas d’animosité pour les neo￾atlantes, en revanche, elle ne considère pas les hyperboréens comme des Aseryns.","source_pages":[29,29],"source_designation":"Duché d’Amunghol (suppléante) : Maarashana"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Mary Shanasti"],["Âge apparent","28 ans"],["Nationalité déclarée","indienne"]]},{"type":"p","text":"Mary Shanasti est une « enders », elle est une sorte de gourou qui possède des communautés sous-marines indépendantes. Elle prône des principes religieux néopaïens, elle n’a que faire des lois, puisque ses communautés sont soumises à la loi de sa propre « nation »."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","(suppléant) Duché d’Amunghol : Maarashana"],["Nom de la Réalité","Mary Shanasti"],["Nom de la Vérité","Maarashana"],["Âge complet","28 ans en apparence ; âge réel inconnu"],["Affiliations","Crawlers : Enders"],["Nationalité d’origine","indienne"],["Nature réelle","demi-Aseryne, semi-daemone (Lemurianne)"],["Statut","Duchesse Suppléante"]]},{"type":"p","style":"lore","text":"Fille d’Alabor, cette semi-aseryne est une demi-déesse puissante, elle n’a que des aserynes et de nymphes marines dans ses communautés, elle est farouchement opposée à Seawares et tout impact corporatif alors même que les infrastructures sont construites par ces corporations cherchant à s’installer sous l’eau. Elle était l’ancienne duchesse d’amunghol mais son caractère orageux n’était pas très apprécié et finalement, Amnudya lui fut préférée. Quand elle s’énerve, elle provoque presque toujours la pluie. Les daemons de sa mère la craignent comme la peste, car elle supprime aussi instinctivement leurs pouvoirs pour se les approprier temporairement. Elle déteste les Mûliens, qu’elle trouve présomptueux et stupides mais n’a pas d’animosité pour les neo-atlantes, en revanche, elle ne considère pas les hyperboréens comme des Aseryns."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-shanelias-duria-29","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Shanelias Duria","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Lémurie","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Shanelias Duria","nom_verite_source":"Shanelias Duria","race":"Aseryne (lemurianne)","age":"Âge inconnu","origine":"Lemurianne","statut":"Duc Suppléant","affiliations":"Royaume de Lemuria","source_group":"Lémurie","source_order":29,"source_page":29,"identity_keys":["Shanelias Duria"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"(suppléant) Duché de Vundis : Shanelias Duria Nom de la Réalité : _ Nom de la Vérité : Shanelias Duria Age : « ??? » » Affiliations : Royaume de Lemuria Nationalité d’origine : Lemurianne Ethnie réelle : Aseryne (lemurianne) Statut : Duc Suppléant Shanelias est un duc suppléant du domaine de Vundis. Malgré son apparence, c’est un très ancien atlante, le corps qu’il possède est celui d’un de ses descendants. C’était un noble de l’Atlantide qui étudiait la magie et la médecine. Il vint à Lemuria pour combattre les épidémies. Il en repoussa jusqu’à ce que les plus terribles ne frappent. Malade, il se refusa à abandonner son sacerdoce. Alors que sa maladie le détruisait, il s’acharnait à soigner les autres, remplaçant son corps par des parties artificielles qu’il animait avec la magie. Après plus d’un millénaire à ne plus avoir grand-chose de biologique, le golem de Stroethil fut visité par un ancien Azménorien dénommé Thar’lal rark. Il lui révéla qu’il avait emprunté la « Voie » mécanique et qu’il voulait faire de lui un de ses champions. Fervent croyant dans la Création et dans le Temple atlante, Shanelias le rejeta. Thar décida de le punir en lui déposant « l’oxyde », une maladie faisant rouiller et devenir toxique le Stroethil, une nouvelle épidémie souillant désormais non pas le vivant mais l’architecture, les armes, les outils lemurians. Shanelias continua son sacrifice constant pour lutter, s’enfermant rapidement pour contenir « l’Oxyde ». Des siècles plus tard, son descendant, Duria Shen-Xe, le libéra en utilisant de nécromancie pour offrir son corps, afin que le « Médecin » ne sauve l’île d’une nouvelle épidémie. En vie, il lutte contre la « Voie mécanique » et les maladies.","source_pages":[29,29],"source_designation":"Duché de Vundis (suppléant) : Shanelias Duria"},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","(suppléant) Duché de Vundis : Shanelias Duria"],["Nom de la Réalité","_"],["Nom de la Vérité","Shanelias Duria"],["Âge complet","Âge inconnu"],["Affiliations","Royaume de Lemuria"],["Nationalité d’origine","Lemurianne"],["Nature réelle","Aseryne (lemurianne)"],["Statut","Duc Suppléant"]]},{"type":"p","style":"lore","text":"Shanelias est un duc suppléant du domaine de Vundis. Malgré son apparence, c’est un très ancien atlante, le corps qu’il possède est celui d’un de ses descendants. C’était un noble de l’Atlantide qui étudiait la magie et la médecine. Il vint à Lemuria pour combattre les épidémies. Il en repoussa jusqu’à ce que les plus terribles ne frappent. Malade, il se refusa à abandonner son sacerdoce. Alors que sa maladie le détruisait, il s’acharnait à soigner les autres, remplaçant son corps par des parties artificielles qu’il animait avec la magie. Après plus d’un millénaire à ne plus avoir grand-chose de biologique, le golem de Stroethil fut visité par un ancien Azménorien dénommé Thar’lal rark. Il lui révéla qu’il avait emprunté la « Voie » mécanique et qu’il voulait faire de lui un de ses champions. Fervent croyant dans la Création et dans le Temple atlante, Shanelias le rejeta. Thar décida de le punir en lui déposant « l’oxyde », une maladie faisant rouiller et devenir toxique le Stroethil, une nouvelle épidémie souillant désormais non pas le vivant mais l’architecture, les armes, les outils lemurians. Shanelias continua son sacrifice constant pour lutter, s’enfermant rapidement pour contenir « l’Oxyde ». Des siècles plus tard, son descendant, Duria Shen-Xe, le libéra en utilisant de nécromancie pour offrir son corps, afin que le « Médecin » ne sauve l’île d’une nouvelle épidémie. En vie, il lutte contre la « Voie mécanique » et les maladies."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-aseryns-terres-temples-siegorn-akryth-30","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Siegorn Akryth","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Hyperborée","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Siegorn Akryth","nom_verite_source":"Siegorn Akryth","race":"Aseryne (hyperboréenne)","age":"13 ans en apparence ; âge réel inconnu","origine":"Hyperboréenne","statut":"Roi des Hyperboréens","affiliations":"_","source_group":"Hyperborée","source_order":30,"source_page":33,"identity_keys":["Siegorn","Siegorn Akryth"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Trône royal : Siegorn Nom de la Réalité : _ Nom de la Vérité : Siegorn Akryth Age : «13 ans » - ??? ans Affiliations : _ Nationalité d’origine : Hyperboréenne Ethnie réelle : Aseryne (hyperboréenne) Statut : Roi des Hyperboréens Siegorn est le fils actuel le plus âgé de la reine Hildeveig. Malgré ses airs de jeune de 13 ans, il a quelques siècles mais ne parvient pas à mûrir. Les magiciens de la cour du Valhollis ont comploté pour le maudire, supposant la reine-mère d’avoir ses enfants avec le Fléau. Ses frères et sœurs sont détenus par les magiciens. La vérité est pire que leurs plus grandes craintes, puisque chaque enfant qu’elle fait depuis la mort de Budli est, non pas un enfant d’Akryth, mais un fragment d’Akryth en personne. Et chaque fois qu’on les tue, ils fusionnent dans le corps de l’ainé en vie. Hildeveig espère le diviser comme le fut Sharith autrefois, mais la folie de ses fils les mène à une mort rapide, comme si le Fléau les poussait à en finir. Siegorn n’est pas tendre ni même stupide, il se sait maudit même s’il ne sait pas ce qu’il est en réalité. Il sait que ses ainés finissent fous et que personne ne le respecte, alors son règne est assez rude et tyrannique puisque pour asseoir son autorité, il se montre impitoyable. Pour déjouer l’image d’enfant qu’il possède, il a deux épouses et porte son armure en permanence. Il est, comme sa mère, le seul aseryn à posséder la « foudre givrante ». Ironie du sort, en étant maintenu jeune, les magiciens l’ont stabilisé, il ne semble pas atteint de paranoïa et de mégalomanie comparables à ses ainés. L’éveil de Sharith l’a également renforcé.","source_pages":[33,33],"source_designation":"Trône royal : Siegorn"},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Trône royal : Siegorn"],["Nom de la Réalité","_"],["Nom de la Vérité","Siegorn Akryth"],["Âge complet","13 ans en apparence ; âge réel inconnu"],["Affiliations","_"],["Nationalité d’origine","Hyperboréenne"],["Nature réelle","Aseryne (hyperboréenne)"],["Statut","Roi des Hyperboréens"]]},{"type":"p","style":"lore","text":"Siegorn est le fils actuel le plus âgé de la reine Hildeveig. Malgré ses airs de jeune de 13 ans, il a quelques siècles mais ne parvient pas à mûrir. Les magiciens de la cour du Valhollis ont comploté pour le maudire, supposant la reine-mère d’avoir ses enfants avec le Fléau. Ses frères et sœurs sont détenus par les magiciens. La vérité est pire que leurs plus grandes craintes, puisque chaque enfant qu’elle fait depuis la mort de Budli est, non pas un enfant d’Akryth, mais un fragment d’Akryth en personne. Et chaque fois qu’on les tue, ils fusionnent dans le corps de l’ainé en vie. Hildeveig espère le diviser comme le fut Sharith autrefois, mais la folie de ses fils les mène à une mort rapide, comme si le Fléau les poussait à en finir. Siegorn n’est pas tendre ni même stupide, il se sait maudit même s’il ne sait pas ce qu’il est en réalité. Il sait que ses ainés finissent fous et que personne ne le respecte, alors son règne est assez rude et tyrannique puisque pour asseoir son autorité, il se montre impitoyable. Pour déjouer l’image d’enfant qu’il possède, il a deux épouses et porte son armure en permanence. Il est, comme sa mère, le seul aseryn à posséder la « foudre givrante ». Ironie du sort, en étant maintenu jeune, les magiciens l’ont stabilisé, il ne semble pas atteint de paranoïa et de mégalomanie comparables à ses ainés. L’éveil de Sharith l’a également renforcé."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-aseryns-terres-temples-hildeveig-eijnir-31","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Hildeveig Eijnir","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Hyperborée","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Hildeveig Eijnir","nom_verite_source":"Hildeveig Eijnir","race":"Aseryne (hyperboréenne)","age":"45 ans en apparence ; âge réel inconnu","origine":"Hyperboréenne","statut":"Reine-mère des Hyperboréens","affiliations":"_","source_group":"Hyperborée","source_order":31,"source_page":33,"identity_keys":["Hildeveig Eijnir"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Reine-mère : Hildeveig Eijnir Nom de la Réalité : _ Nom de la Vérité : Hildeveig Eijnir Age : « 45 ans » - ???? ans Affiliations : _ Nationalité d’origine : Hyperboréenne Ethnie réelle : Aseryne (hyperboréenne) Statut : Reine-mère des Hyperboréens Hildeveig était une noble guerrière, dotée du sang amazone et Aseryne, elle détenait l’épée d’Angrboda. Chaque fois qu’Akryth s’éveillait totalement, elle prenait un groupe de guerriers et piégeait le fléau, souvent en le trompant afin de lui faire boire un alcool si fort qu’il l’endormait. Quand l’Atlantide sombra, elle endossa la responsabilité de recevoir les exilés de l’Atlantide, sans poursuivre la guerre contre eux et défia Akryth afin de non plus l’endormir mais le tuer. Elle se fit massacrer et les Hyperboréens quittèrent l’île, abandonnant leur reine. Akryth en fit sa servante et au fil des siècles, elle prépara un plan pour le vaincre. Hélas hautement corrompue par lui quand elle arriva à ses fins, c’est en tant que Fléau supérieur que son peuple la retrouva après quelques siècles à les appeler une fois victorieuse. Frustrée et haineuse qu’on ne se méfie d’elle, elle ne laissa rien paraitre, se pliant à leurs exigences, cédant la couronne à un marin lambda, acceptant sa fille comme reine, obéissant, mais sa rage restait présente et quand elle ne put la contenir, elle négocia avec Akryth, le laissant investir son corps pour naitre autant qu’il ne le voulait, en échange de ses pouvoirs permanents. Elle est la vraie reine mais elle craint son fils, car si Akryth s’éveillait, elle serait inutile.","source_pages":[33,33],"source_designation":"Reine-mère : Hildeveig Eijnir"},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Reine-mère : Hildeveig Eijnir"],["Nom de la Réalité","_"],["Nom de la Vérité","Hildeveig Eijnir"],["Âge complet","45 ans en apparence ; âge réel inconnu"],["Affiliations","_"],["Nationalité d’origine","Hyperboréenne"],["Nature réelle","Aseryne (hyperboréenne)"],["Statut","Reine-mère des Hyperboréens"]]},{"type":"p","style":"lore","text":"Hildeveig était une noble guerrière, dotée du sang amazone et Aseryne, elle détenait l’épée d’Angrboda. Chaque fois qu’Akryth s’éveillait totalement, elle prenait un groupe de guerriers et piégeait le fléau, souvent en le trompant afin de lui faire boire un alcool si fort qu’il l’endormait. Quand l’Atlantide sombra, elle endossa la responsabilité de recevoir les exilés de l’Atlantide, sans poursuivre la guerre contre eux et défia Akryth afin de non plus l’endormir mais le tuer. Elle se fit massacrer et les Hyperboréens quittèrent l’île, abandonnant leur reine. Akryth en fit sa servante et au fil des siècles, elle prépara un plan pour le vaincre. Hélas hautement corrompue par lui quand elle arriva à ses fins, c’est en tant que Fléau supérieur que son peuple la retrouva après quelques siècles à les appeler une fois victorieuse. Frustrée et haineuse qu’on ne se méfie d’elle, elle ne laissa rien paraitre, se pliant à leurs exigences, cédant la couronne à un marin lambda, acceptant sa fille comme reine, obéissant, mais sa rage restait présente et quand elle ne put la contenir, elle négocia avec Akryth, le laissant investir son corps pour naitre autant qu’il ne le voulait, en échange de ses pouvoirs permanents. Elle est la vraie reine mais elle craint son fils, car si Akryth s’éveillait, elle serait inutile."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-aseryns-terres-temples-aslie-evans-32","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Aslie Evans","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Hyperborée","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Aslie Evans","real_name_source":"Aslie Evans","nom_verite":"Aslaug Eyvaldottir","nom_verite_source":"Aslaug Eyvaldottir","race":"Aseryne (Hyperboréenne)","age":"24 ans","origine":"Islandaise","statut":"reine","affiliations":"Gouvernement : police","source_group":"Hyperborée","source_order":32,"source_page":34,"identity_keys":["Aslaug Eyvaldottir","Aslie Evans"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Reine : Aslaug Eyvaldottir Nom de la Réalité : Aslie Evans Nom de la Vérité : Aslaug Eyvaldottir Age : «24 ans » - ??? Affiliations : Gouvernement : police Nationalité d’origine : Islandaise Ethnie réelle : Aseryne (Hyperboréenne) Statut : reine Aslie Evans est une secrétaire détachée au QG de la police de Los Angeles. Blonde pimpante, elle est toujours serviable et sans histoire. Elle semble être une grande sœur aimante envers son petit frère, Sieg. Aslaug est une reine d’Hyperborée, elle est la première épouse de Siegorn, le roi. Elle appartient à la maison Valgardis, la maison des ducs de Volkvangra, puisqu’elle était l’héritière avant son mariage. Elle n’a pas eu le choix d’épouser « l’enfant » mais elle noua un lien d’affection malgré tout. Elle voit Siegorn comme un fils ou un petit frère mais comprend son mal-être et son besoin de sembler plus mature. Comme elle perdit son droit d’héritage du duché, elle n’a pas grand-chose à faire au palais de Valhollis et c’est pourquoi elle voyage souvent en Californie. Récemment, elle se fit embaucher à la police comme secrétaire et n’est donc pas retournée à Hyperborée depuis des mois. Son but est de trouver le mage Saint-Germain afin de forcer le vieillissement de son mari. Elle l’ignore mais elle est surveillée par les princesses Mûliennes, notamment l’impitoyable Saerith qui veut l’offrir à son père, Kyriak, afin d’obtenir des droits sur Hyperborée. Elle était aussi surveillée par Drasko Vladic mais après la « pluie des Anges », il abandonna l’idée de l’approcher, ayant mieux à faire.","source_pages":[34,34],"source_designation":"Reine : Aslaug Eyvaldottir"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Aslie Evans"],["Âge apparent","24 ans"],["Nationalité déclarée","Islandaise"]]},{"type":"p","text":"Aslie Evans est une secrétaire détachée au QG de la police de Los Angeles. Blonde pimpante, elle est toujours serviable et sans histoire. Elle semble être une grande sœur aimante envers son petit frère, Sieg."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Reine : Aslaug Eyvaldottir"],["Nom de la Réalité","Aslie Evans"],["Nom de la Vérité","Aslaug Eyvaldottir"],["Âge complet","24 ans en apparence ; âge réel inconnu"],["Affiliations","Gouvernement : police"],["Nationalité d’origine","Islandaise"],["Nature réelle","Aseryne (Hyperboréenne)"],["Statut","reine"]]},{"type":"p","style":"lore","text":"Aslaug est une reine d’Hyperborée, elle est la première épouse de Siegorn, le roi. Elle appartient à la maison Valgardis, la maison des ducs de Volkvangra, puisqu’elle était l’héritière avant son mariage. Elle n’a pas eu le choix d’épouser « l’enfant » mais elle noua un lien d’affection malgré tout. Elle voit Siegorn comme un fils ou un petit frère mais comprend son mal-être et son besoin de sembler plus mature. Comme elle perdit son droit d’héritage du duché, elle n’a pas grand-chose à faire au palais de Valhollis et c’est pourquoi elle voyage souvent en Californie. Récemment, elle se fit embaucher à la police comme secrétaire et n’est donc pas retournée à Hyperborée depuis des mois. Son but est de trouver le mage Saint-Germain afin de forcer le vieillissement de son mari. Elle l’ignore mais elle est surveillée par les princesses Mûliennes, notamment l’impitoyable Saerith qui veut l’offrir à son père, Kyriak, afin d’obtenir des droits sur Hyperborée. Elle était aussi surveillée par Drasko Vladic mais après la « pluie des Anges », il abandonna l’idée de l’approcher, ayant mieux à faire."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
export default PAYLOAD;
